e(\\\\n91:       `SELECT * FROM event_sequence WHERE aggregate_id IN (${sessionIds.map(() => ''''''''?'''''''').join('''''''','''''''')})`\\\\n92:     ).all(...sessionIds)\\\\n93:   : [];\\\\n94: \\\\n95: const projectDirs = db.prepare(\\\\n96:   ''''''''SELECT * FROM project_directory WHERE project_id = ?''''''''\\\\n97: ).all(projectId);\\\\n98: \\\\n99: db.close();\\\\n100: \\\\n101: const lines = [];\\\\n102: lines.push(''''''''-- OPENCODE_CONVERSATION_BACKUP'''''''');\\\\n103: lines.push(''''''''-- version: 1'''''''');\\\\n104: lines.push(`-- export_time: ${new Date().toISOString()}`);\\\\n105: if (gitRemote) lines.push(`-- git_remote: ${gitRemote}`);\\\\n106: lines.push(`-- source_worktree: ${worktree}`);\\\\n107: lines.push(`-- source_project_id: ${projectId}`);\\\\n108: lines.push(`-- session_count: ${sessions.length}`);\\\\n109: lines.push(`-- message_count: ${messages.length}`);\\\\n110: lines.push(`-- part_count: ${parts.length}`);\\\\n111: lines.push(`-- event_sequence_count: ${eventSequences.length}`);\\\\n112: lines.push(`-- todo_count: ${todos.length}`);\\\\n113: lines.push(`-- session_message_count: ${sessionMessages.length}`);\\\\n114: lines.push('''''''''''''''');\\\\n115: \\\\n116: const projectCols = [''''''''id'''''''', ''''''''worktree'''''''', ''''''''vcs'''''''', ''''''''name'''''''', ''''''''icon_url'''''''', ''''''''icon_color'''''''',\\\\n117:   ''''''''time_created'''''''', ''''''''time_updated'''''''', ''''''''time_initialized'''''''', ''''''''sandboxes'''''''', ''''''''commands'''''''', ''''''''icon_url_override''''''''];\\\\n118: lines.push(genInsert(''''''''project'''''''', projectCols, project));\\\\n119: \\\\n120: if (projectDirs.length > 0) {\\\\n121:   lines.push(genInsert(''''''''project_directory'''''''',\\\\n122:     [''''''''project_id'''''''', ''''''''directory'''''''', ''''''''type'''''''', ''''''''strategy'''''''', ''''''''time_created''''''''], projectDirs));\\\\n123: }\\\\n124: if (sessions.length > 0) {\\\\n125:   lines.