es = db.prepare(\\n22:   \\\"SELECT id FROM message WHERE session_id = ? AND json_extract(data, ''''$.role'''') = ''''user'''' ORDER BY time_created ASC\\\"\\n23: ).all(sessionId);\\n24: \\n25: const userTexts = userMessages.map(m => {\\n26:   const parts = db.prepare(\\n27:     \\\"SELECT data FROM part WHERE message_id = ? AND json_extract(data, ''''$.type'''') = ''''text'''' ORDER BY time_created ASC LIMIT 1\\\"\\n28:   ).all(m.id);\\n29:   if (parts.length > 0) {\\n30:     try {\\n31:       const data = JSON.parse(parts[0].data);\\n32:       return data.text || '''''''';\\n33:     } catch {\\n34:       return '''''''';\\n35:     }\\n36:   }\\n37:   return '''''''';\\n38: });\\n39: \\n40: const triggerPhrases = [''''对话备份'''', ''''对话导入'''', ''''conversation-backup'''', ''''conversation-backup''''];\\n41: const isBackupCommand = userTexts.length === 1 && triggerPhrases.some(p => userTexts[0].includes(p));\\n42: \\n43: console.log(JSON.stringify({\\n44:   session_id: sessionId,\\n45:   session_title: session.title,\\n46:   user_message_count: userTexts.length,\\n47:   first_user_message: userTexts[0] || '''''''',\\n48:   is_new_session: isBackupCommand,\\n49: }, null, 2));\\n50: \\n51: db.close();\\n\\n(End of file - total 51 lines)\\n</content>\",\"metadata\":{\"preview\":\"#!/usr/bin/env node\\nconst { DatabaseSync } = require(''''node:sqlite'''');\\nconst os = require(''''os'''');\\nconst path = require(''''path'''');\\n\\nconst dbPath = path.join(os.homedir(), ''''.local'''', ''''share'''', ''''opencode'''', ''''opencode.db'''');\\nconst db = new DatabaseSync(dbPath, { readOnly: true });\\n\\nconst session = db.prepare(\\n  ''''SELECT id, title FROM session ORDER BY time_created DESC LIMIT 1''''\\n).get();\\n\\nif (!session) {\\n  console.log(JSON.stringify({ error: ''''No session found'''' }));\\n  db.close();\\n  process.exit(1);\\n}\\n\\nconst sessionId = session.id;\\n\",\"truncated\":false,\"loaded\":[],\"display\":{\"type\":\"file\",\"path\":\"D:\\\\BaiduSyncdisk\\\\all_code\\\\candywall-skills\\\\conversation-backup\\\\scripts\\\\check_session.js\",\"text\":\"#!/usr/bin/env node\\nconst { DatabaseSync } = require(''''node:sqlite'''');\\nconst os = require(''''os'''');\\nconst path = require(''''path'''');\\n\\nconst dbPath = path.join(os.homedir(), ''''.local'''', ''''share'''', ''''opencode'''', ''''opencode.db'''');\\nconst db = new DatabaseSync(dbPath, { readOnly: true });\\n\\nconst session = db.prepare(\\n  ''''SELECT id, title FROM session ORDER BY time_created DESC LIMIT 1''''\\n).get();\\n\\nif (!session) {\\n  console.log(JSON.stringify({ error: ''''No session found'''' }));\\n  db.close();\\n  process.exit(1);\\n}\\n\\nconst sessionId = session.id;\\n\\nconst userMessages = db.prepare(\\n  \\\"SELECT id FROM message WHERE session_id = ? AND json_extract(data, ''''$.role'''') = ''''user'''' ORDER BY time_created ASC\\\"\\n).all(sessionId);\\n\\nconst userTexts = userMessages.map(m => {\\n  const parts = db.prepare(\\n    \\\"SELECT data FROM part WHERE message_id = ? AND json_extract(data, ''''$.type'''') = ''''text'''' ORDER BY time_created ASC LIMIT 1\\\"\\n  ).all(m.id);\\n  if (parts.length > 0) {\\n    try {\\n      const data = JSON.parse(parts[0].data);\\n      return data.text || '''''''';\\n    } catch {\\n      return '''''''';\\n    }\\n  }\\n  return '''''''';\\n});\\n\\nconst triggerPhrases = [''''对话备份'''', ''''对话导入'''', ''''conversation-backup'''', ''''conversation-backup''''];\\nconst isBackupCommand = userTexts.length === 1 && triggerPhrases.some(p => userTexts[0].includes(p));\\n\\nconsole.log(JSON.stringify({\\n  session_id: sessionId,\\n  session_title: session.title,\\n  user_message_count: userTexts.length,\\n  first_user_message: userTexts[0] || '''''''',\\n  is_new_session: isBackupCommand,\\n}, null, 2));\\n\\ndb.close();\",\"lineStart\":1,\"lineEnd\":51,\"totalLines\":51,\"truncated\":false}},\"title\":\"BaiduSyncdisk\\\\all_code\\\\candywall-skills\\\\conversation-backup\\\\scripts\\\\check_session.js\",\"time\":{\"start\":1783855093864,\"end\":1783855093875}}}''),\n-(''prt_f560c99740011h8xH15667XP5h'', ''msg_f560c8b35001XNZAaIn9aQgpDD'', ''ses_0a9fbb56effeQaZdXvhiM6xltc'', 1783855094132, 1783855094468, ''{\"type\":\"tool\",\"tool\":\"read\",\"callID\":\"call_6c0ab3a144b74149ab40d512\",\"state\":{\"status\":\"completed\",\"input\":{\"filePath\":\"D:\\\\BaiduSyncdisk\\\\all_code\\\\candywall-skills\\\\conversation-backup\\\\scripts\\\\export_conversations.js\"},\"output\":\"<path>D:\\\\BaiduSyncdisk\\\\all_code\\\\candywall-skills\\\\conversation-backup\\\\scripts\\\\export_conversations.js</path>\\n<type>file</type>\\n<content>\\n1: #!/usr/bin/env node\\n2: const { DatabaseSync } = require(''''node:sqlite'''');\\n3: const fs = require(''''fs'''');\\n4: const path = require(''''path'''');\\n5: const { execSync } = require(''''child_process'''');\\n6: const os = require(''''os'''');\\n7: \\n8: let projectDir = null;\\n9: let excludeSessionId = null;\\n10: \\n11: for (let i = 2; i < process.argv.length; i++) {\\n12:   if (process.argv[i] === ''''--exclude-session'''') {\\n13:     excludeSessionId = process.argv[++i];\\n14:   } else {\\n15:     projectDir = path.resolve(process.argv[i]);\\n16:   }\\n17: }\\n18: \\n19: if (!projectDir) projectDir = process.cwd();\\n20: const worktree = projectDir.replace(/\\\\\\\\/g, ''''/'''');\\n21: \\n22: const dbPath = path.join(os.homedir(), ''''.local'''', ''''share'''', ''''opencode'''', ''''opencode.db'''');\\n23: if (!fs.existsSync(dbPath)) {\\n24:   console.error(`opencode.db not found at: ${dbPath}`);\\n25:   process.exit(1);\\n26: }\\n27: \\n28: const db = new DatabaseSync(dbPath, { readOnly: true });\\n29: \\n30: const project = db.prepare(\\n31:   ''''SELECT * FROM project WHERE worktree = ?''''\\n32: ).get(worktree);\\n33: \\n34: if (!project) {\\n35:   console.error(`Project not found for worktree: ${worktree}`);\\n36:   process.exit(1);\\n37: }\\n38: \\n39: const projectId = project.id;\\n40: \\n41: let gitRemote = '''''''';\\n42: try {\\n43:   gitRemote = execSync(''''git remote get-url origin'''', { cwd: projectDir, encoding: ''''utf8'''' }).trim();\\n44: } catch {}\\n45: \\n46: let sessions = db.prepare(\\n47:   ''''SELECT * FROM session WHERE project_id = ? AND time_archived IS NULL''''\\n48: ).all(projectId);\\n49: \\n50: if (excludeSessionId) {\\n51:   sessions = sessions.filter(s => s.id !== excludeSessionId);\\n52: }\\n53: \\n54: const sessionIds = sessions.map(s => s.id);\\n55: \\n56: // 统计每个会话的消息数量\\n57: const messageCounts = sessionIds.length > 0\\n58:   ? db.prepare(\\n59:       `SELECT session_id, COUNT(*) as count FROM message WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')}) GROUP BY session_id`\\n60:     ).all(...sessionIds)\\n61:   : [];\\n62: \\n63: const messageCountMap = new Map(messageCounts.map(m => [m.session_id, m.count]));\\n64: \\n65: const messages = sessionIds.length > 0\\n66:   ? db.prepare(\\n67:       `SELECT * FROM message WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n68:     ).all(...sessionIds)\\n69:   : [];\\n70: \\n71: const parts = sessionIds.length > 0\\n72:   ? db.prepare(\\n73:       `SELECT * FROM part WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n74:     ).all(...sessionIds)\\n75:   : [];\\n76: \\n77: const todos = sessionIds.length > 0\\n78:   ? db.prepare(\\n79:       `SELECT * FROM todo WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n80:     ).all(...sessionIds)\\n81:   : [];\\n82: \\n83: const sessionMessages = sessionIds.length > 0\\n84:   ? db.prepare(\\n85:       `SELECT * FROM session_message WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n86:     ).all(...sessionIds)\\n87:   : [];\\n88: \\n89: const eventSequences = sessionIds.length > 0\\n90:   ? db.prepare(\\n91:       `SELECT * FROM event_sequence WHERE aggregate_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n92:     ).all(...sessionIds)\\n93:   : [];\\n94: \\n95: const projectDirs = db.prepare(\\n96:   ''''SELECT * FROM project_directory WHERE project_id = ?''''\\n97: ).all(projectId);\\n98: \\n99: db.close();\\n100: \\n101: const lines = [];\\n102: lines.push(''''-- OPENCODE_CONVERSATION_BACKUP'''');\\n103: lines.push(''''-- version: 1'''');\\n104: lines.push(`-- export_time: ${new Date().toISOString()}`);\\n105: if (gitRemote) lines.push(`-- git_remote: ${gitRemote}`);\\n106: lines.push(`-- source_worktree: ${worktree}`);\\n107: lines.push(`-- source_project_id: ${projectId}`);\\n108: lines.push(`-- session_count: ${sessions.length}`);\\n109: lines.push(`-- message_count: ${messages.length}`);\\n110: lines.push(`-- part_count: ${parts.length}`);\\n111: lines.push(`-- event_sequence_count: ${eventSequences.length}`);\\n112: lines.push(`-- todo_count: ${todos.length}`);\\n113: lines.push(`-- session_message_count: ${sessionMessages.length}`);\\n114: lines.push('''''''');\\n115: \\n116: const projectCols = [''''id'''', ''''worktree'''', ''''vcs'''', ''''name'''', ''''icon_url'''', ''''icon_color'''',\\n117:   ''''time_created'''', ''''time_updated'''', ''''time_initialized'''', ''''sandboxes'''', ''''commands'''', ''''icon_url_override''''];\\n118: lines.push(genInsert(''''project'''', projectCols, project));\\n119: \\n120: if (projectDirs.length > 0) {\\n121:   lines.push(genInsert(''''project_directory'''',\\n122:     [''''project_id'''', ''''directory'''', ''''type'''', ''''strategy'''', ''''time_created''''], projectDirs));\\n123: }\\n124: if (sessions.length > 0) {\\n125:   lines.push(genInsert(''''session'''', getCols(''''session'''', sessions[0]), sessions));\\n126: }\\n127: if (messages.length > 0) {\\n128:   lines.push(genInsert(''''message'''', getCols(''''message'''', messages[0]), messages));\\n129: }\\n130: if (parts.length > 0) {\\n131:   lines.push(genInsert(''''part'''', getCols(''''part'''', parts[0]), parts));\\n132: }\\n133: if (todos.length > 0)