{ readOnly: true });\\n29: \\n30: const project = db.prepare(\\n31:   ''''SELECT * FROM project WHERE worktree = ?''''\\n32: ).get(worktree);\\n33: \\n34: if (!project) {\\n35:   console.error(`Project not found for worktree: ${worktree}`);\\n36:   process.exit(1);\\n37: }\\n38: \\n39: const projectId = project.id;\\n40: \\n41: let gitRemote = '''''''';\\n42: try {\\n43:   gitRemote = execSync(''''git remote get-url origin'''', { cwd: projectDir, encoding: ''''utf8'''' }).trim();\\n44: } catch {}\\n45: \\n46: let sessions = db.prepare(\\n47:   ''''SELECT * FROM session WHERE project_id = ? AND time_archived IS NULL''''\\n48: ).all(projectId);\\n49: \\n50: if (excludeSessionId) {\\n51:   sessions = sessions.filter(s => s.id !== excludeSessionId);\\n52: }\\n53: \\n54: const sessionIds = sessions.map(s => s.id);\\n55: \\n56: // 统计每个会话的消息数量\\n57: const messageCounts = sessionIds.length > 0\\n58:   ? db.prepare(\\n59:       `SELECT session_id, COUNT(*) as count FROM message WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')}) GROUP BY session_id`\\n60:     ).all(...sessionIds)\\n61:   : [];\\n62: \\n63: const messageCountMap = new Map(messageCounts.map(m => [m.session_id, m.count]));\\n64: \\n65: const messages = sessionIds.length > 0\\n66:   ? db.prepare(\\n67:       `SELECT * FROM message WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n68:     ).all(...sessionIds)\\n69:   : [];\\n70: \\n71: const parts = sessionIds.length > 0\\n72:   ? db.prepare(\\n73:       `SELECT * FROM part WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n74:     ).all(...sessionIds)\\n75:   : [];\\n76: \\n77: const todos = sessionIds.length > 0\\n78:   ? db.prepare(\\n79:       `SELECT * FROM todo WHERE session_id IN (${sessionIds.map(() => ''''?'''').join('''','''')})`\\n80:     ).all(...sessionIds)\\n81:   : [];\\n82: \\n83: const sessionMessages = sessionIds.length > 0\\n84:   ? db.prepare(\\n85:       `SELECT * FROM se