2: \n43: console.log(JSON.stringify({\n44:   session_id: sessionId,\n45:   session_title: session.title,\n46:   user_message_count: userTexts.length,\n47:   first_user_message: userTexts[0] || '''',\n48:   is_new_session: isBackupCommand,\n49: }, null, 2));\n50: \n51: db.close();\n\n(End of file - total 51 lines)\n</content>","metadata":{"preview":"#!/usr/bin/env node\nconst { DatabaseSync } = require(''node:sqlite'');\nconst os = require(''os'');\nconst path = require(''path'');\n\nconst dbPath = path.join(os.homedir(), ''.local'', ''share'', ''opencode'', ''opencode.db'');\nconst db = new DatabaseSync(dbPath, { readOnly: true });\n\nconst session = db.prepare(\n  ''SELECT id, title FROM session ORDER BY time_created DESC LIMIT 1''\n).get();\n\nif (!session) {\n  console.log(JSON.stringify({ error: ''No session found'' }));\n  db.close();\n  process.exit(1);\n}\n\nconst sessionId = session.id;\n","truncated":false,"loaded":[],"display":{"type":"file","path":"D:\\BaiduSyncdisk\\all_code\\candywall-skills\\conversation-backup\\scripts\\check_session.js","text":"#!/usr/bin/env node\nconst { DatabaseSync } = require(''node:sqlite'');\nconst os = require(''os'');\nconst path = require(''path'');\n\nconst dbPath = path.join(os.homedir(), ''.local'', ''share'', ''opencode'', ''opencode.db'');\nconst db = new DatabaseSync(dbPath, { readOnly: true });\n\nconst session = db.prepare(\n  ''SELECT id, title FROM session ORDER BY time_created DESC LIMIT 1''\n).get();\n\nif (!session) {\n  console.log(JSON.stringify({ error: ''No session found'' }));\n  db.close();\n  process.exit(1);\n}\n\nconst sessionId = session.id;\n\nconst userMessages = db.prepare(\n  \"SELECT id FROM message WHERE session_id = ? AND json_extract(data, ''$.role'') = ''user'' ORDER BY time_created ASC\"\n).all(sessionId);\n\nconst userTexts = userMessages.map(m => {\n  const parts = db.prepare(\n    \"SELECT data FROM part WHERE message_id = ? AND json_extract(data, ''$.type'') = ''text'' ORDER BY time_created ASC LIMIT 1\"\n  ).all(m.id);\n  if (parts.length > 0) {\n    try {\n      const data = JSON.parse(parts[0].data);\n      return data.text || '''';\n    } catch {\n      return '''';\n    }\n  }\n  return '''';\n});\n\nconst triggerPhrases = [''对话备份'', ''对话导入'', ''conversation-backup'', ''conversation-backup''];\nconst isBackupCommand = userTexts.length === 1 && triggerPhrases.some(p => userTexts[0].includes(p));\n\nconsole.log(JSON.stringify({\n  session_id: sessionId,\n  session_title: session.title,\n  user_message_count: userTexts.length,\n  first_user_message: userTexts[0] || '''',\n  is_new_session: isBackupCommand,\n}, null, 2));\n\ndb.close();","lineStart":1,"lineEnd":51,"totalLines":51,"truncated":false}},"title":"BaiduSyncdisk\\all_code\\candywall-skills\\conversation-backup\\scripts\\check_session.js","time":{"start":1783855093864,"end":1783855093875}}}'),
('prt_f560c99740011h8xH15667XP5h', 'msg_f560c8b35001XNZAaIn9aQgpDD', 'ses_0a9fbb56effeQaZdXvhiM6xltc', 1783855094132, 1783855094468, '{"type":"tool","tool":"read","callID":"call_6c0ab3a144b74149ab40d512","state":{"status":"completed","input":{"filePath":"D:\\BaiduSyncdisk\\all_code\\candywall-skills\\conversation-backup\\scripts\\export_conversations.js"},"output":"<path>D:\\BaiduSyncdisk\\all_code\\candywall-skills\\conversation-backup\\scripts\\export_conversations.js</path>\n<type>file</type>\n<content>\n1: #!/usr/bin/env node\n2: const { DatabaseSync } = require(''node:sqlite'');\n3: const fs = require(''fs'');\n4: const path = require(''path'');\n5: const { execSync } = require(''child_process'');\n6: const os = require(''os'');\n7: \n8: let projectDir = null;\n9: let excludeSessionId = null;\n10: \n11: for (let i = 2; i < process.argv.length; i++) {\n12:   if (process.argv[i] === ''--exclude-session'') {\n13:     excludeSessionId = process.argv[++i];\n14:   } else {\n15:     projectDir = path.resolve(process.argv[i]);\n16:   }\n17: }\n18: \n19: if (!projectDir) projectDir = process.cwd();\n20: const worktree = projectDir.replace(/\\\\/g, ''/'');\n21: \n22: const dbPath = path.join(os.homedir(), ''.local'', ''share'', ''opencode'', ''opencode.db'');\n23: if (!fs.existsSync(dbPath)) {\n24:   console.error(`opencode.db not found at: ${dbPath}`);\n25:   process.exit(1);\n26: }\n27: \n28: const db = new DatabaseSync(dbPath, { readOnly: true });\n29: \n30: const project = db.prepare(\n31:   ''SELECT * FROM project WHERE worktree = ?''\n32: ).get(worktree);\n33: \n34: if (!project) {\n35:   console.error(`Project not found for worktree: ${worktree}`);\n36:   process.exit(1);\n37: }\n38: \n39: const projectId = project.id;\n40: \n41: let gitRemote = '''';\n42: try {\n43:   gitRemote = execSync(''git remote get-url origin'', { cwd: projectDir, encoding: ''utf8'' }).trim();\n44: } catch {}\n45: \n46: let sessions = db.prepare(\n47:   ''SELECT * FROM session WHERE project_id = ? AND time_archived IS NULL''\n48: ).all(projectId);\n49: \n50: if (excludeSessionId) {\n51:   sessions = sessions.filter(s => s.id !== excludeSessionId);\n52: }\n53: \n54: const sessionIds = sessions.map(s => s.id);\n55: \n56: // 统计每个会话的消息数量\n57: const messageCounts = sessionIds.length > 0\n58:   ? db.prepare(\n59:       `SELECT session_id, COUNT(*) as count FROM message WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')}) GROUP BY session_id`\n60:     ).all(...sessionIds)\n61:   : [];\n62: \n63: const messageCountMap = new Map(messageCounts.map(m => [m.session_id, m.count]));\n64: \n65: const messages = sessionIds.length > 0\n66:   ? db.prepare(\n67:       `SELECT * FROM message WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n68:     ).all(...sessionIds)\n69:   : [];\n70: \n71: const parts = sessionIds.length > 0\n72:   ? db.prepare(\n73:       `SELECT * FROM part WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n74:     ).all(...sessionIds)\n75:   : [];\n76: \n77: const todos = sessionIds.length > 0\n78:   ? db.prepare(\n79:       `SELECT * FROM todo WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n80:     ).all(...sessionIds)\n81:   : [];\n82: \n83: const sessionMessages = sessionIds.length > 0\n84:   ? db.prepare(\n85:       `SELECT * FROM session_message WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n86:     ).all(...sessionIds)\n87:   : [];\n88: \n89: const eventSequences = sessionIds.length > 0\n90:   ? db.prepare(\n91:       `SELECT * FROM event_sequence WHERE aggregate_id IN (${sessionIds.map(() => ''?'').join('','')})`\n92:     ).all(...sessionIds)\n93:   : [];\n94: \n95: const projectDirs = db.prepare(\n96:   ''SELECT * FROM project_directory WHERE project_id = ?''\n97: ).all(projectId);\n98: \n99: db.close();\n100: \n101: const lines = [];\n102: lines.push(''-- OPENCODE_CONVERSATION_BACKUP'');\n103: lines.push(''-- version: 1'');\n104: lines.push(`-- export_time: ${new Date().toISOString()}`);\n105: if (gitRemote) lines.push(`-- git_remote: ${gitRemote}`);\n106: lines.push(`-- source_worktree: ${worktree}`);\n107: lines.push(`-- source_project_id: ${projectId}`);\n108: lines.push(`-- session_count: ${sessions.length}`);\n109: lines.push(`-- message_count: ${messages.length}`);\n110: lines.push(`-- part_count: ${parts.length}`);\n111: lines.push(`-- event_sequence_count: ${eventSequences.length}`);\n112: lines.push(`-- todo_count: ${todos.length}`);\n113: lines.push(`-- session_message_count: ${sessionMessages.length}`);\n114: lines.push('''');\n115: \n116: const projectCols = [''id'', ''worktree'', ''vcs'', ''name'', ''icon_url'', ''icon_color'',\n117:   ''time_created'', ''time_updated'', ''time_initialized'', ''sandboxes'', ''commands'', ''icon_url_override''];\n118: lines.push(genInsert(''project'', projectCols, project));\n119: \n120: if (projectDirs.length > 0) {\n121:   lines.push(genInsert(''project_directory'',\n122:     [''project_id'', ''directory'', ''type'', ''strategy'', ''time_created''], projectDirs));\n123: }\n124: if (sessions.length > 0) {\n125:   lines.push(genInsert(''session'', getCols(''session'', sessions[0]), sessions));\n126: }\n127: if (messages.length > 0) {\n128:   lines.push(genInsert(''message'', getCols(''message'', messages[0]), messages));\n129: }\n130: if (parts.length > 0) {\n131:   lines.push(genInsert(''part'', getCols(''part'', parts[0]), parts));\n132: }\n133: if (todos.length > 0) {\n134:   lines.push(genInsert(''todo'', getCols(''todo'', todos[0]), todos));\n135: }\n136: if (sessionMessages.length > 0) {\n137:   lines.push(genInsert(''session_message'', getCols(''session_message'', sessionMessages[0]), sessionMessages));\n138: }\n139: if (eventSequences.length > 0) {\n140:   lines.push(genInsert(''event_sequence'', getCols(''event_sequence'', eventSequences[0]), eventSequences));\n141: }\n142: \n143: let sql = lines.join(''\\n'');\n144: \n145: sql = replaceAll(sql, projectId, ''{{PROJECT_ID}}'');\n146: \n147: const segments = worktree.split(''/'').filter(Boolean);\n148: const escapedSegs = segments.map(s => s.replace(/[.*+?^${}()|[\\]]/g, ''\\\\$&''));\n149: const pathRegex = new RegExp(escapedSegs.join(''[/\\\\\\\\]+''), ''g'');\n150: sql = sql.replace(pathRegex, ''{{WORKTREE}}'');\n151: \n152: const outDir = path.join(projectDir, ''.opencode'');\n153: if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });\n154: const outPath = path.join(outDir, ''conversations.sql'');\n155: fs.writeFileSync(outPath, sql, ''utf8'');\n156: \n157: // 生成会话摘要（标题 + 轮次）\n158: const sessionsSummary = sessions.map(s => ({\n159:   title: s.title || ''(无标题)'',\n160:   rounds: messageCountMap.get(s.id) || 0\n161: }));\n162: \n163: // 生成准确的 commit message\n164: const now = new Date();\n165: const timestamp = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, ''0'')}-${String(now.getDate()).padStart(2, ''0'')} ${String(now.getHours()).padStart(2, ''0'')}:${String(now.getMinutes()).padStart(2, ''0'')}:${String(now.getSeconds()).padStart(2, ''0'')}`;\n166: const totalRounds = sessionsSummary.reduce((sum, s) => sum + s.rounds, 0);\n167: const commitMessageLines = [\n168:   `【导出opencode对话记录】截止${timestamp}`,\n169:   ``,\n170:   `摘要：共 ${sessions.length} 个对话，${totalRounds} 轮对话`,\n171:   ``,\n172:   `各对话详情：`\n173: ];\n174: sessionsSummary.forEach(s => {\n175:   commitMessageLines.push(`- ${s.title} (${s.rounds}轮)`);\n176: });\n177: const commitMessage = commitMessageLines.join(''\\n'');\n178: \n179: console.log(JSON.stringify({\n180:   success: true,\n181:   output: outPath,\n182:   project_id: projectId,\n183:   worktree,\n184:   git_remote: gitRemote,\n185:   excluded_session: excludeSessionId || null,\n186:   sessions_summary: sessionsSummary,\n187:   commit_message: commitMessage,\n188:   counts: {\n189:     project: 1,\n190:     project_directory: projectDirs.length,\n191:     session: sessions.length,\n192:     message: messages.length,\n193:     part: parts.length,\n194:     event_sequence: eventSequences.length,\n195:     todo: todos.length,\n196:     session_message: sessionMessages.length,\n197:   }\n198: }, null, 2));\n199: \n200: function replaceAll(str, search, replacement) {\n201:   if (!search) return str;\n202:   return str.split(search).join(replacement);\n203: }\n204: \n205: function getCols(_table, row) {\n206:   return Object.keys(row);\n207: }\n208: \n209: function genInsert(table, cols, rows) {\n210:   const arr = Array.isArray(rows) ? rows : [rows];\n211:   if (arr.length === 0) return '''';\n212:   const colStr = cols.join('', '');\n213:   const valRows = arr.map(row => {\n214:     const vals = cols.map(c => formatVal(row[c])).join('', '');\n215:     return `(${vals})`;\n216:   });\n217:   return `INSERT OR REPLACE INTO ${table} (${colStr}) VALUES\\n${valRows.join('',\\n'')};`;\n218: }\n219: \n220: function formatVal(v) {\n221:   if (v === null || v === undefined) return ''NULL'';\n222:   if (typeof v === ''number'') return String(v);\n223:   return `''${String(v).replace(/''/g, \"''''\")}''`;\n224: }\n\n(End of file - total 224 lines)\n</content>","metadata":{"preview":"#!/usr/bin/env node\nconst { DatabaseSync } = require(''node:sqlite'');\nconst fs = require(''fs'');\nconst path = require(''path'');\nconst { execSync } = require(''child_process'');\nconst os = require(''os'');\n\nlet projectDir = null;\nlet excludeSessionId = null;\n\nfor (let i = 2; i < process.argv.length; i++) {\n  if (process.argv[i] === ''--exclude-session'') {\n    excludeSessionId = process.argv[++i];\n  } else {\n    projectDir = path.resolve(process.argv[i]);\n  }\n}\n\nif (!projectDir) projectDir = process.cwd();\nconst worktree = projectDir.replace(/\\\\/g, ''/'');","truncated":false,"loaded":[],"display":{"type":"file","path":"D:\\BaiduSyncdisk\\all_code\\candywall-skills\\conversation-backup\\scripts\\export_conversations.js","text":"#!/usr/bin/env node\nconst { DatabaseSync } = require(''node:sqlite'');\nconst fs = require(''fs'');\nconst path = require(''path'');\nconst { execSync } = require(''child_process'');\nconst os = require(''os'');\n\nlet projectDir = null;\nlet excludeSessionId = null;\n\nfor (let i = 2; i < process.argv.length; i++) {\n  if (process.argv[i] === ''--exclude-session'') {\n    excludeSessionId = process.argv[++i];\n  } else {\n    projectDir = path.resolve(process.argv[i]);\n  }\n}\n\nif (!projectDir) projectDir = process.cwd();\nconst worktree = projectDir.replace(/\\\\/g, ''/'');\n\nconst dbPath = path.join(os.homedir(), ''.local'', ''share'', ''opencode'', ''opencode.db'');\nif (!fs.existsSync(dbPath)) {\n  console.error(`opencode.db not found at: ${dbPath}`);\n  process.exit(1);\n}\n\nconst db = new DatabaseSync(dbPath, { readOnly: true });\n\nconst project = db.prepare(\n  ''SELECT * FROM project WHERE worktree = ?''\n).get(worktree);\n\nif (!project) {\n  console.error(`Project not found for worktree: ${worktree}`);\n  process.exit(1);\n}\n\nconst projectId = project.id;\n\nlet gitRemote = '''';\ntry {\n  gitRemote = execSync(''git remote get-url origin'', { cwd: projectDir, encoding: ''utf8'' }).trim();\n} catch {}\n\nlet sessions = db.prepare(\n  ''SELECT * FROM session WHERE project_id = ? AND time_archived IS NULL''\n).all(projectId);\n\nif (excludeSessionId) {\n  sessions = sessions.filter(s => s.id !== excludeSessionId);\n}\n\nconst sessionIds = sessions.map(s => s.id);\n\n// 统计每个会话的消息数量\nconst messageCounts = sessionIds.length > 0\n  ? db.prepare(\n      `SELECT session_id, COUNT(*) as count FROM message WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')}) GROUP BY session_id`\n    ).all(...sessionIds)\n  : [];\n\nconst messageCountMap = new Map(messageCounts.map(m => [m.session_id, m.count]));\n\nconst messages = sessionIds.length > 0\n  ? db.prepare(\n      `SELECT * FROM message WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n    ).all(...sessionIds)\n  : [];\n\nconst parts = sessionIds.length > 0\n  ? db.prepare(\n      `SELECT * FROM part WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n    ).all(...sessionIds)\n  : [];\n\nconst todos = sessionIds.length > 0\n  ? db.prepare(\n      `SELECT * FROM todo WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n    ).all(...sessionIds)\n  : [];\n\nconst sessionMessages = sessionIds.length > 0\n  ? db.prepare(\n      `SELECT * FROM session_message WHERE session_id IN (${sessionIds.map(() => ''?'').join('','')})`\n    ).all(...sessionIds)\n  : [];\n\nconst eventSequences = sessionIds.length > 0\n  ? db.prepare(\n      `SELECT * FROM event_sequence WHERE aggregate_id IN (${sessionIds.map(() => ''?'').join('','')})`\n    ).all(...sessionIds)\n  : [];\n\nconst projectDirs = db.prepare(\n  ''SELECT * FROM project_directory WHERE project_id = ?''\n).all(projectId);\n\ndb.close();\n\nconst lines = [];\nlines.push(''-- OPENCODE_CONVERSATION_BACKUP'');\nlines.push(''-- version: 1'');\nlines.push(`-- export_time: ${new Date().toISOString()}`);\nif (gitRemote) lines.push(`-- git_remote: ${gitRemote}`);\nlines.push(`-- source_worktree: ${worktree}`);\nlines.push(`-- source_project_id: ${projectId}`);\nlines.push(`-- session_count: ${sessions.length}`);\nlines.push(`-- message_count: ${messages.length}`);\nlines.push(`-- part_count: ${parts.length}`);\nlines.push(`-- event_sequence_count: ${eventSequences.length}`);\nlines.push(`-- todo_count: ${todos.length}`);\nlines.push(`-- session_message_count: ${sessionMessages.length}`);\nlines.push('''');\n\nconst projectCols = [''id'', ''worktree'', ''vcs'', ''name'', ''icon_url'', ''icon_color'',\n  ''time_created'', ''time_updated'', ''time_initialized'', ''sandboxes'', ''commands'', ''icon_url_override''];\nlines.push(genInsert(''project'', projectCols, project));\n\nif (projectDirs.length > 0) {\n  lines.push(genInsert(''project_directory'',\n    [''project_id'', ''directory'', ''type'', ''strategy'', ''time_created''], projectDirs));\n}\nif (sessions.length > 0) {\n  lines.push(genInsert(''session'', getCols(''session'', sessions[0]), sessions));\n}\nif (messages.length > 0) {\n  lines.push(genInsert(''message'', getCols(''message'', messages[0]), messages));\n}\nif (parts.length > 0) {\n  lines.push(genInsert(''part'', getCols(''part'', parts[0]), parts));\n}\nif (todos.length > 0) {\n  lines.push(genInsert(''todo'', getCols(''todo'', todos[0]), todos));\n}\nif (sessionMessages.length > 0) {\n  lines.push(genInsert(''session_message'', getCols(''session_message'', sessionMessages[0]), sessionMessages));\n}\nif (eventSequences.length > 0) {\n  lines.push(genInsert(''event_sequence'', getCols(''event_sequence'', eventSequences[0]), eventSequences));\n}\n\nlet sql = lines.join(''\\n'');\n\nsql = replaceAll(sql, projectId, ''{{PROJECT_ID}}'');\n\nconst segments = worktree.split(''/'').filter(Boolean);\nconst escapedSegs = segments.map(s => s.replace(/[.*+?^${}()|[\\]]/g, ''\\\\$&''));\nconst pathRegex = new RegExp(escapedSegs.join(''[/\\\\\\\\]+''), ''g'');\nsql = sql.replace(pathRegex, ''{{WORKTREE}}'');\n\nconst outDir = path.join(projectDir, ''.opencode'');\nif (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });\nconst outPath = path.join(outDir, ''conversations.sql'');\nfs.writeFileSync(outPath, sql, ''utf8'');\n\n// 生成会话摘要（标题 + 轮次）\nconst sessionsSummary = sessions.map(s => ({\n  title: s.title || ''(无标题)'',\n  rounds: messageCountMap.get(s.id) || 0\n}));\n\n// 生成准确的 commit message\nconst now = new Date();\nconst timestamp = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, ''0'')}-${String(now.getDate()).padStart(2, ''0'')} ${String(now.getHours()).padStart(2, ''0'')}:${String(now.getMinutes()).padStart(2, ''0'')}:${String(now.getSeconds()).padStart(2, ''0'')}`;\nconst totalRounds = sessionsSummary.reduce((sum, s) => sum + s.rounds, 0);\nconst commitMessageLines = [\n  `【导出opencode对话记录】截止${timestamp}`,\n  ``,\n  `摘要：共 ${sessions.length} 个对话，${totalRounds} 轮对话`,\n  ``,\n  `各对话详情：`\n];\nsessionsSummary.forEach(s => {\n  commitMessageLines.push(`- ${s.title} (${s.rounds}轮)`);\n});\nconst commitMessage = commitMessageLines.join(''\\n'');\n\nconsole.log(JSON.stringify({\n  success: true,\n  output: outPath,\n  project_id: projectId,\n  worktree,\n  git_remote: gitRemote,\n  excluded_session: excludeSessionId || null,\n  sessions_summary: sessionsSummary,\n  commit_message: commitMessage,\n  counts: {\n    project: 1,\n    project_directory: projectDirs.length,\n    session: sessions.length,\n    message: messages.length,\n    part: parts.length,\n    event_sequence: eventSequences.length,\n    todo: todos.length,\n    session_message: sessionMessages.length,\n  }\n}, null, 2));\n\nfunction replaceAll(str, search, replacement) {\n  if (!search) return str;\n  return str.split(search).join(replacement);\n}\n\nfunction getCols(_table, row) {\n  return Object.keys(row);\n}\n\nfunction genInsert(table, cols, rows) {\n  const arr = Array.isArray(rows) ? rows : [rows];\n  if (arr.length === 0) return '''';\n  const colStr = cols.join('', '');\n  const valRows = arr.map(row => {\n    const vals = cols.map(c => formatVal(row[c])).join('', '');\n    return `(${vals})`;\n  });\n  return `INSERT OR REPLACE INTO ${table} (${colStr}) VALUES\\n${valRows.join('',\\n'')};`;\n}\n\nfunction formatVal(v) {\n  if (v === null || v === undefined) return ''NULL'';\n  if (typeof v === ''number'') return String(v);\n  return `''${String(v).replace(/''/g, \"''''\")}''`;\n}","lineStart":1,"lineEnd":224,"totalLines":224,"truncated":false}},"title":"BaiduSyncdisk\\all_code\\candywall-skills\\conversation-backup\\scripts\\export_conversations.js","time":{"start":1783855094454,"end":1783855094467}}}'),
